function formatPrice(value: number) {
  return `₩${new Intl.NumberFormat('ko-KR').format(value)}`;
}

function renderLandingMarkup(nowMs: number) {
  const earlyBirdActive = isEarlyBirdActiveAt(nowMs);
  let markup = pageMarkup;

  if (!earlyBirdActive) {
    markup = markup.replace(
      /\n\s*<div class="earlybird-note">[\s\S]*?<\/div>\n\n      <div class="pricing-grid">/,
      '\n\n      <div class="pricing-grid">',
    );
  }

  landingPriceCards.forEach(card => {
    const pricing = getProgramPricing(card.programId, nowMs);
    if (!pricing) return;

    if (earlyBirdActive) {
      markup = markup.replace(
        `<div class="card-original-price">정가 ${card.regularText}</div>\n          <div class="card-price-row">\n            <span class="card-price">${card.earlyBirdText}</span>`,
        `<div class="card-original-price">정가 ${formatPrice(pricing.regularPriceKrw)}</div>\n          <div class="card-price-row">\n            <span class="card-price">${formatPrice(pricing.finalPriceKrw)}</span>`,
      );
      return;
    }

    markup = markup.replace(
      `<div class="card-original-price">정가 ${card.regularText}</div>\n          <div class="card-price-row">\n            <span class="card-price">${card.earlyBirdText}</span>`,
      `<div class="card-price-row">\n            <span class="card-price">${formatPrice(pricing.regularPriceKrw)}</span>`,
    );
    markup = markup.replace(`\n          <div class="discount-badge">${card.discountLabel}</div>`, '');
  });

  return markup;
}

export default function LandingPageClient({ initialNowMs }: { initialNowMs: number }) {
  const renderedMarkup = renderLandingMarkup(initialNowMs);

  useEffect(() => {
    document.querySelectorAll<HTMLButtonElement>('.faq-q').forEach(btn => {
      btn.addEventListener('click', () => {
        const item = btn.parentElement;
        if (!item) return;

        const isOpen = item.classList.contains('active');
        document.querySelectorAll('.faq-item.active').forEach(el => {
          el.classList.remove('active');
          el.querySelector('.faq-q')?.setAttribute('aria-expanded', 'false');
        });
        if (!isOpen) {
          item.classList.add('active');
          btn.setAttribute('aria-expanded', 'true');
        }
      });
    });

    document.querySelectorAll<HTMLButtonElement>('.coach-tab').forEach(tab => {
      tab.addEventListener('click', () => {
        document.querySelectorAll('.coach-tab').forEach(t => t.classList.remove('active'));
        document.querySelectorAll('.coach-panel').forEach(p => p.classList.remove('active'));
        tab.classList.add('active');
        const panel = document.getElementById('panel-' + tab.dataset.tab);
        if (panel) panel.classList.add('active');
      });
    });

    document.querySelectorAll('.testimonial-card').forEach(card => {
      card.addEventListener('mouseenter', () => {
        const track = document.querySelector<HTMLElement>('.carousel-track');
        if (track) track.style.animationPlayState = 'paused';
      });
      card.addEventListener('mouseleave', () => {
        const track = document.querySelector<HTMLElement>('.carousel-track');
        if (track) track.style.animationPlayState = 'running';
      });
    });
    const msUntilEarlyBirdEnds = EARLY_BIRD_END_AT_MS - initialNowMs;
    const earlyBirdTimer = msUntilEarlyBirdEnds > 0
      ? window.setTimeout(() => {
        window.location.reload();
      }, msUntilEarlyBirdEnds + 1000)
      : null;

    return () => {
      if (earlyBirdTimer) window.clearTimeout(earlyBirdTimer);
    };
  }, [initialNowMs]);

  return (
    <>
      <style dangerouslySetInnerHTML={{ __html: pageStyles }} />
      <div dangerouslySetInnerHTML={{ __html: renderedMarkup }} />
    </>
  );
}
